16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "bulk_signup_warning")
67	    private Boolean bulkSignupWarning;
68	
69	    @Column(name = "household_size")
70	    private Integer householdSize;
71	
72	    @Column(name = "postcode")
73	    private String postcode;
74	
75	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
76	    private Set<Pet> pets;
77	
78	    public String getAddress() {
79	        return this.address;
80	    }
81	
82	    public void setAddress(String address) {
83	        this.address = address;
84	    }
85	
86	    public String getCity() {
87	        return this.city;
88	    }
89	
90	    public void setCity(String city) {
91	        this.city = city;
92	    }
93	
94	    public String getTelephone() {
95	        return this.telephone;
96	    }
97	
98	    public void setTelephone(String telephone) {
99	        this.telephone = telephone;
100	    }
101	
102	    public String getEmail() {
103	        return this.email;
104	    }
105	
106	    public void setEmail(String email) {
107	        this.email = email;
108	    }
109	
110	    public LocalDate getRegistrationDate() {
111	        return this.registrationDate;
112	    }
113	
114	    public void setRegistrationDate(LocalDate registrationDate) {
115	        this.registrationDate = registrationDate;
116	    }
117	
118	    public String getCustomerCode() {
119	        return this.customerCode;
120	    }
121	
122	    public void setCustomerCode(String customerCode) {
123	        this.customerCode = customerCode;
124	    }
125	
126	    public String getHouseholdId() {
127	        return this.householdId;
128	    }
129	
130	    public void setHouseholdId(String householdId) {
131	        this.householdId = householdId;
132	    }
133	
134	    public Integer getNamesakeCount() {
135	        return this.namesakeCount;
136	    }
137	
138	    public void setNamesakeCount(Integer namesakeCount) {
139	        this.namesakeCount = namesakeCount;
140	    }
141	
142	    public Boolean getBulkSignupWarning() {
143	        return this.bulkSignupWarning;
144	    }
145	
146	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
147	        this.bulkSignupWarning = bulkSignupWarning;
148	    }
149	
150	    public Integer getHouseholdSize() {
151	        return this.householdSize;
152	    }
153	
154	    public void setHouseholdSize(Integer householdSize) {
155	        this.householdSize = householdSize;
156	    }
157	
158	    public String getPostcode() {
159	        return this.postcode;
160	    }
161	
162	    public void setPostcode(String postcode) {
163	        this.postcode = postcode;
164	    }
165	
166	    /**
167	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY
168	     * is the last two digits of the registration date's year (e.g. {@code "SMI-0007-M26"}).
169	     * Derived from the owner's own fields, so it stays consistent with them.
170	     */
171	    @Transient
172	    public String getMembershipNumber() {
173	        if (this.customerCode == null || this.registrationDate == null) {
174	            return null;
175	        }
176	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
177	    }
178	
179	    /**
180	     * The owner's membership level, a number from 1 to 3. Every owner starts at level 1;
181	     * one level is added when an email is on file and one more when the owner is unique
182	     * (namesake count of zero). The level is capped at 3, leaving level 4 reserved for
183	     * tenure. Derived from the owner's own fields, so it stays consistent with them.
184	     */
185	    @Transient
186	    public Integer getMembershipLevel() {
187	        int level = 1;
188	        boolean hasEmail = this.email != null && !this.email.isEmpty();
189	        if (hasEmail) {
190	            level++;
191	        }
192	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
193	        if (unique) {
194	            level++;
195	        }
196	        return Math.min(level, 3);
197	    }
198	
199	    /**
200	     * The owner's locality: the canonical region. This prefers the postcode, resolving the
201	     * region whose range contains it (see {@link RegionPostcodeTable}), and only falls back
202	     * to the city via the fixed {@link CityRegionTable} when the postcode is absent or in no
203	     * known range. Derived from the owner's own fields, so it stays consistent with them.
204	     */
205	    @Transient
206	    public String getLocality() {
207	        return RegionPostcodeTable.regionFor(this.postcode)
208	            .orElseGet(() -> CityRegionTable.regionFor(this.city));
209	    }
210	
211	    /**
212	     * The owner's preferred contact channel: {@code "EMAIL"} when an email address is on
213	     * file, otherwise {@code "PHONE"}. Derived from the owner's own contact details, so it
214	     * stays consistent with them.
215	     */
216	    @Transient
217	    public String getContactPreference() {
218	        boolean hasEmail = this.email != null && !this.email.isEmpty();
219	        return hasEmail ? "EMAIL" : "PHONE";
220	    }
221	
222	    /**
223	     * The owner's identity key: the single derived value used to detect duplicate owners,
224	     * formed as {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
225	     * Two owners are duplicates only when their whole identity keys are equal, so members
226	     * of one household (sharing a household id) but with different telephones stay distinct.
227	     * Derived from the owner's own fields, so it stays consistent with them.
228	     */
229	    @Transient
230	    public String getIdentityKey() {
231	        String telephonePart = this.telephone == null ? "" : this.telephone;
232	        String emailPart = this.email == null ? "" : this.email;
233	        String householdPart = this.householdId == null ? "" : this.householdId;
234	        return telephonePart + "|" + emailPart + "|" + householdPart;
235	    }
236	
237	    /**
238	     * Normalize the registration date before persisting: default it to the server's
239	     * current date when none was supplied, then roll it forward onto a business day so
240	     * every newly persisted owner is registered on a weekday.
241	     */
242	    @PrePersist
243	    void normalizeRegistrationDate() {
244	        if (this.registrationDate == null) {
245	            this.registrationDate = LocalDate.now();
246	        }
247	        this.registrationDate = BusinessDay.rollForward(this.registrationDate);
248	    }
249	
250	    protected Set<Pet> getPetsInternal() {
251	        if (this.pets == null) {
252	            this.pets = new HashSet<>();
253	        }
254	        return this.pets;
255	    }
256	
257	    protected void setPetsInternal(Set<Pet> pets) {
258	        this.pets = pets;
259	    }
260	
261	    public List<Pet> getPets() {
262	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
263	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
264	        return Collections.unmodifiableList(sortedPets);
265	    }
266	
267	    public void setPets(List<Pet> pets) {
268	        this.pets = new HashSet<>(pets);
269	    }
