18	
19	import java.util.Map;
20	import java.util.Optional;
21	import java.util.regex.Pattern;
22	
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Normalizes and validates an owner's telephone number into E.164 form.
27	 *
28	 * <p>A leading {@code '+'} and country code are kept when present; otherwise the
29	 * default country code {@link #DEFAULT_COUNTRY_CODE} is assumed and a single
30	 * leading {@code '0'} is dropped from the national digits. Spaces, dashes and
31	 * brackets are stripped. The result is only accepted when it carries between
32	 * {@link #MIN_DIGITS} and {@link #MAX_DIGITS} digits after the {@code '+'} and,
33	 * for a recognised country code, exactly as many national digits as that
34	 * country requires (see {@link #NATIONAL_DIGITS_BY_COUNTRY_CODE}).
35	 */
36	@Component
37	public class TelephoneNormalizer {
38	
39	    /** Country code assumed when the raw number has no explicit {@code '+'} prefix. */
40	    public static final String DEFAULT_COUNTRY_CODE = "61";
41	
42	    /** The fewest digits a valid E.164 number may have after the {@code '+'}. */
43	    public static final int MIN_DIGITS = 8;
44	
45	    /** The most digits a valid E.164 number may have after the {@code '+'}. */
46	    public static final int MAX_DIGITS = 15;
47	
48	    /**
49	     * Exact national-number length required for each recognised E.164 country
50	     * calling code. Country codes form a prefix-free set, so at most one entry
51	     * matches a given number; codes not listed here are subject only to the
52	     * generic {@link #MIN_DIGITS}/{@link #MAX_DIGITS} bounds.
53	     */
54	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY_CODE =
55	        Map.of("1", 10, "61", 9);
56	
57	    /** Separators that carry no numeric meaning and are stripped before parsing. */
58	    private static final Pattern SEPARATORS = Pattern.compile("[\\s()\\-]");
59	
60	    private static final Pattern DIGITS = Pattern.compile("\\d+");
61	
62	    /**
63	     * Convert a raw telephone value into its E.164 representation.
64	     *
65	     * @param telephone the raw telephone value (may be {@code null})
66	     * @return the E.164 number (e.g. {@code "+61412345678"}), or
67	     *         {@link Optional#empty()} if it cannot form a valid E.164 number
68	     */
69	    public Optional<String> toE164(String telephone) {
70	        if (telephone == null) {
71	            return Optional.empty();
72	        }
73	        String trimmed = telephone.trim();
74	        boolean explicitCountryCode = trimmed.startsWith("+");
75	        String body = explicitCountryCode ? trimmed.substring(1) : trimmed;
76	        String digits = SEPARATORS.matcher(body).replaceAll("");
77	        if (!DIGITS.matcher(digits).matches()) {
78	            return Optional.empty();
79	        }
80	        if (!explicitCountryCode) {
81	            String national = digits.startsWith("0") ? digits.substring(1) : digits;
82	            digits = DEFAULT_COUNTRY_CODE + national;
83	        }
84	        if (digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS) {
85	            return Optional.empty();
86	        }
87	        if (!hasValidNationalLength(digits)) {
88	            return Optional.empty();
89	        }
90	        return Optional.of("+" + digits);
91	    }
92	
93	    /**
94	     * Check that the national number has the exact length its country code
95	     * requires. Numbers whose country code is not recognised are accepted here;
96	     * only the generic length bounds constrain them.
97	     *
98	     * @param digits the E.164 digits (country code followed by the national number)
99	     * @return {@code true} if the national-number length matches the country code
100	     */
101	    private boolean hasValidNationalLength(String digits) {
102	        return NATIONAL_DIGITS_BY_COUNTRY_CODE.entrySet().stream()
103	            .filter(entry -> digits.startsWith(entry.getKey()))
104	            .findFirst()
105	            .map(entry -> digits.length() - entry.getKey().length() == entry.getValue())
106	            .orElse(true);
107	    }
108	}
