25	/**
26	 * Validates an owner's postcode. A postcode is optional, but when supplied it must be
27	 * exactly four digits and fall within the range valid for the region derived from the
28	 * owner's city (see {@link CityRegionTable} and {@link RegionPostcodeTable}). A city
29	 * whose region has no known range accepts any 4-digit postcode.
30	 */
31	@Component
32	public class PostcodeValidator {
33	
34	    private static final Pattern FOUR_DIGITS = Pattern.compile("\\d{4}");
35	
36	    /**
37	     * @param postcode a supplied (non-{@code null}) postcode value
